package uk.ac.ravensbourne.casevault.repository;
import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; import uk.ac.ravensbourne.casevault.domain.CaseRecord;
public interface CaseRepository extends JpaRepository<CaseRecord,UUID> { Optional<CaseRecord> findByIdAndOrganisationId(UUID id, UUID organisationId); List<CaseRecord> findByOrganisationIdAndOwnerAnalystId(UUID organisationId, UUID ownerAnalystId); @org.springframework.data.jpa.repository.Query("select count(a)>0 from CaseAssignment a where a.caseRecord.id=:caseId and a.analyst.id=:analystId") boolean existsAssignment(@org.springframework.data.repository.query.Param("caseId") UUID caseId,@org.springframework.data.repository.query.Param("analystId") UUID analystId); }
